/* === 作者：song === */
/* === ❗这是公开社区的免费美化，除此之外的任何来源都是盗传盗用 === */
/* === 禁止二传/商用，二改请标源 === */

/* === 导入字体 ，参考墨千尾老师=== */
@import url("https://fontsapi.zeoseven.com/482/main/result.css"); /* CooperZhengKai */
@import url('https://fontsapi.zeoseven.com/970/main/result.css'); /* XuanZongTi 玄宗体 *//* 全局基础样式 */
body,
#options,
#quick-reply-menu,
#customCSS,
#completion_prompt_manager_list,
#settings_preset_openai,
#context_story_string,
.text_pole,
#send_textarea {
  font-family: 'CooperZhengKai', 'GenWanMin2 TC R', sans-serif; 
  font-weight: normal;
  font-style: normal;
}

/* ================= 导航栏左上角装饰 ================= */
#top-bar::before {
    content: '';
    display: block;
    position: absolute;
    width: 100%;
    height: 60px;
    background-image: url('https://iili.io/BTcxap4.png');
    background-size: contain;           /* 保持图片不被裁剪 */
    background-repeat: no-repeat;
    background-position: -3% center;    /* 负值向左偏移，让图片部分露出 */
    margin-top: 20px;
    pointer-events: none;
    transform: scale(1.4);              /* 调整大小 */
    transform-origin: left top;         /* 从左上角缩放，适合左上角定位 */
    z-index: 3;
}

/* ================= 气泡装饰 ================= */
.mes {
    position: relative !important;
}

.mes::before {
    content: '' !important;
    position: absolute !important;
    top: -75px !important;
    left: -35px !important;
    width: 300px !important;
    height: 250px !important;
    background-image: url('https://iili.io/BTcxjvj.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 15 !important;
}

.mes::after {
    content: '' !important;
    position: absolute !important;
    bottom: -15px !important;
    left: -20px !important;
    width: 100px !important;
    height: 100px !important;
    background-image: url('https://iili.io/BTcImkG.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 15 !important;
}

/* ================= 顶栏图标 ================= */
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden;
}
#top-settings-holder .drawer-icon {
    display: block;
    margin: 0 1px;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 32px !important;
    height: 32px !important;
    opacity: 1 !important;
}
.drawer-icon.fa-fw:hover {
    transform: scale(1.1);
}
.drawer-icon.fa-sliders,
.drawer-icon.fa-font,
.drawer-icon.fa-user-cog,
.drawer-icon.fa-cubes,
.drawer-icon.fa-address-card,
.drawer-icon.fa-plug,
.drawer-icon.fa-book-atlas,
.drawer-icon.fa-panorama,
.drawer-icon.fa-face-smile {
    background-image: url('https://iili.io/BulW8Lg.png') !important;
}
#top-settings-holder .drawer .drawer-icon.openIcon {
    transform: scale(1.1);
}
/* 顶栏背景颜色 */
#top-bar,
.top-bar,
.header,
#top-settings-holder,
.drawer-header,
.navbar,
[class*="top-bar"],
[class*="header"] {
    background: rgba(249, 211, 210, 0.5) !important;
}

/* 强制固定顶栏高度 */
#top-settings-holder,
.drawer-header,
.top-bar {
    display: flex !important;
    align-items: center !important;
    height: 32px !important;        /* 强制固定高度，而不是最小高度 */
    min-height: 20px !important;    /* 同时限制最小 */
    max-height: 36px !important;    /* 同时限制最大 */
    line-height: 1 !important;
    overflow: visible !important;   /* 防止内容被裁剪 */
}
/* ================= 底栏（精简版 - 无多余边框） ================= */
#form_sheld {
    position: absolute;
    bottom: 10px;
    left: 0;
    right: 0;
    background: transparent !important;
    margin: 8px !important;
    width: 95% !important;
    display: flex !important;
    justify-content: center !important;
    padding: 0 !important;
}

/* 只保留这一个容器有背景色 */
#send_form {
    background: rgba(249, 211, 210, 0.5) !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 6px 12px !important;
    width: 90% !important;
    display: flex !important;
}

/* 内部容器全部透明 */
#send_textarea,
#leftSendForm,
#nonQRFormItems {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

#send_textarea {
    color: #333 !important;
    font-size: 14px !important;
    padding: 8px 12px !important;
    flex: 7 !important;
    resize: none !important;
    outline: none !important;
}

#leftSendForm {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
}

#nonQRFormItems {
    flex: 1 !important;
    position: relative !important;
}

/* 统一去除所有边框圆角阴影 */
#form_sheld, #send_form, #send_textarea, #leftSendForm, #nonQRFormItems,
.qr--buttons, #qr--bar {
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

/* 图标样式保持不变 */
#options_button::before,
#send_but::before,
#mes_stop i::before {
    content: '' !important;
    display: inline-block !important;
    width: 48px !important;
    height: 48px !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}

#options_button::before {
    background-image: url('https://iili.io/BTcob7j.png') !important;
}

#send_form #leftSendForm #extensionsMenuButton::before {
    content: '' !important;
    display: inline-block !important;
    width: 50px !important;
    height: 50px !important;
    background-image: url('https://iili.io/BTcoMdJ.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    position: relative !important;
    top: 3px !important;  
}

#send_but::before {
    background-image: url('https://iili.io/BTcIwXV.png') !important;
}

#mes_stop i::before {
    background-image: url('https://iili.io/BTcx9IV.png') !important;
}

/* 占位符文字 */
#send_textarea::placeholder {
    color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "✿忽惊春到小桃枝✿" !important;
    position: absolute !important;
    left: 100px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    font-size: 14px !important;
    pointer-events: none !important;
    white-space: nowrap !important;
}

/* 隐藏qr，参考nini */
.qr--buttons {
    opacity: 0;
    visibility: hidden;
    max-height: 0;
    transition: opacity 0.3s ease;
}
#send_form:focus-within .qr--buttons {
    opacity: 1;
    visibility: visible;
    max-height: 120px;
}
/* ================= 气泡区域（背景图放在最外层，铺满整个气泡） ================= */
.mes {
    position: relative !important;
    display: flex !important;
    flex-direction: column !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    margin-bottom: 75px !important;
    margin-top: 2px !important;
    width: 90% !important;
    margin-left: auto !important;
    margin-right: auto !important;
    max-width: none !important;
    padding-top: 50px !important;
    padding-bottom: 100px !important;
    overflow: visible !important;
    /* 背景图放在最外层 .mes 上 */
    background-image: url('https://iili.io/BTL3W0v.png') !important;
    background-size: 100% 100% !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-clip: border-box !important;
    border: none !important;
    box-shadow: none !important;
}

/* 确保头像包装器和消息块不遮挡背景 */
.mes .mesAvatarWrapper,
.mes .mes_block {
    position: relative !important;
    z-index: 2 !important;
    background: transparent !important;
}

/* 消息块容器 - 背景透明，不干扰外层背景 */
.mes .mes_block {
    position: relative !important;
    padding: 0 !important;
    margin: 0 !important;
    overflow: visible !important;
    background: transparent !important;
}

/* 文字内容区域 - 背景完全透明，只负责内边距 */
.mes_text {
    padding: 0px 0px 0px 30px !important;
    margin-top: -60px !important;
    margin-bottom: 0 !important;
    z-index: 101 !important;
    font-size: var(--mainFontSize) !important;
    background: transparent !important;
    position: relative !important;
}

/* 最后一条消息微调 */
.mes.last_mes .mes_text {
    margin-top: -80px !important;
}
.mes.last_mes > *:not(.mes_block) {
    padding-bottom: 0px;
}
.mes:first-of-type {
    margin-top: 60px !important;
}
.mes:last-of-type {
    margin-bottom: 130px !important;
}

/* 强制移除任何可能干扰的白色背景 */
.mes,
.mes *,
.mes_block,
.mes_text,
.mesAvatarWrapper {
    background-color: transparent !important;
}

/* 最高优先级：确保 .mes 的背景图不被覆盖 */
.mes {
    background-image: url('https://iili.io/BTL3W0v.png') !important;
    background-size: 100% 100% !important;
    background-repeat: no-repeat !important;
}

/* ================= 头像与新增头像框 ================= */
.mes .avatar {
    width: auto !important;
    height: auto !important;
    display: inline-block !important;
    position: relative !important;
    top: 40px;
    line-height: 0 !important;
    font-size: 0 !important;
    z-index: 10 !important;
}
.mes .avatar img {
    width: 55px !important;
    height: 55px !important;
    box-shadow: none !important;
    object-fit: cover !important;
    border: none !important;
    outline: none !important;
    position: relative !important;
    z-index: 10 !important;
    display: block !important;
    top: -70px !important;
    left: 250px !important;
    transform: translate(0px, 0px) !important;
}

/* 新增头像框伪元素 - 已替换为新图片 */
.mes .avatar::after {
    content: '' !important;
    position: absolute !important;
    top: -112px !important;
    left: 225px !important;
    width: 122px !important;
    height: 122px !important;
    background-image: url('https://iili.io/BuHM5rv.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 15 !important;
}

/* ================= 三元素独立定位 ================= */
.mes .mesAvatarWrapper .mesIDDisplay,
.mes .mesAvatarWrapper .mes_timer,
.mes .mesAvatarWrapper .tokenCounterDisplay {
    font-size: calc(var(--mainFontSize) * 0.85) !important;
    color: #FFA4A1 !important;
}
.mes .mesAvatarWrapper {
    position: relative !important;
}
.mes .mesAvatarWrapper .mesIDDisplay {
    position: absolute !important;
    left: -2px !important;
    top: 11px !important;
    background: transparent !important;
    padding: 0 !important;
    border: none !important;
    white-space: nowrap !important;
    z-index: 20 !important;
    pointer-events: none !important;
}
.mes .mesAvatarWrapper .mes_timer {
    position: absolute !important;
    left: 80px !important;
    top: 22px !important;
    background: transparent !important;
    padding: 0 !important;
    border: none !important;
    white-space: nowrap !important;
    z-index: 20 !important;
    pointer-events: none !important;
}
.mes .mesAvatarWrapper .tokenCounterDisplay {
    position: absolute !important;
    left: 167px !important;
    top: 8px !important;
    background: transparent !important;
    padding: 0 !important;
    border: none !important;
    white-space: nowrap !important;
    z-index: 20 !important;
    pointer-events: none !important;
}
.mes .mesAvatarWrapper .mesIDDisplay::before {
    content: "✿ " !important;
    margin-left: 0px !important;
}
.mes .mesAvatarWrapper .mes_timer::before {
    content: "✿ " !important;
    margin-right: 3px !important;
}
.mes .mesAvatarWrapper .tokenCounterDisplay::before {
    content: "✿" !important;
    margin-right: 3px !important;
}

/* ================= 小铅笔和更多按钮 - 图标替换 + 位置移动 + 修复菜单关闭后消失 ================= */

.mes .mes_buttons {
  position: absolute !important;
  bottom: -105px !important;
  left: 220px !important;
  top: auto !important;
  right: auto !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  z-index: 20 !important;
  pointer-events: auto !important;
  display: flex !important;
  gap: 8px !important;
}

/* 编辑菜单 - 参考nini */
.mes_edit_buttons {
    position: absolute !important;
    bottom: auto !important;
    right: auto !important;
    bottom: -22px !important;
    left: 25px !important;
    transform: none !important;
    z-index: 99999 !important;
    background: transparent !important;
    color: #333 !important;
    padding: 8px 0 !important;
    min-width: 120px !important;
    border: none !important;
    box-shadow: none !important;
}

/* 小铅笔图标 - 已替换为新图片 */
.mes .mes_buttons .fa-pencil,
.mes .mes_buttons .fa-pencil-alt,
.mes .mes_buttons .fa-edit {
  background-image: url('https://iili.io/BTgt9iG.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  font-size: 0 !important;
  width: 20px !important;
  height: 20px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* 更多按钮（三个点）- 已替换为新图片 */
.mes .mes_buttons .fa-ellipsis-h,
.mes .mes_buttons .fa-ellipsis-v,
.mes .mes_buttons .fa-ellipsis {
  background-image: url('https://iili.io/BTgZyVs.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  font-size: 0 !important;
  width: 20px !important;
  height: 20px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* 修复菜单打开/关闭后图标消失的问题 - 更多按钮伪元素 */
.mes .mes_buttons .fa-ellipsis-h::before,
.mes .mes_buttons .fa-ellipsis-v::before,
.mes .mes_buttons .fa-ellipsis::before {
  content: '' !important;
  display: inline-block !important;
  width: 18px !important;
  height: 18px !important;
  background-image: url('https://iili.io/BTgt9iG.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* 强制覆盖菜单关闭后可能产生的样式 - 更多按钮 */
.mes .mes_buttons .fa-ellipsis-h:active,
.mes .mes_buttons .fa-ellipsis-h:focus,
.mes .mes_buttons .fa-ellipsis-h:hover,
.mes .mes_buttons .fa-ellipsis-v:active,
.mes .mes_buttons .fa-ellipsis-v:focus,
.mes .mes_buttons .fa-ellipsis-v:hover,
.mes .mes_buttons .fa-ellipsis:active,
.mes .mes_buttons .fa-ellipsis:focus,
.mes .mes_buttons .fa-ellipsis:hover {
  background-image: url('https://iili.io/BTgt9iG.png') !important;
  opacity: 1 !important;
  visibility: visible !important;
}

.mes .mes_buttons .fa-pencil:active::before,
.mes .mes_buttons .fa-pencil:focus::before,
.mes .mes_buttons .fa-pencil:hover::before,
.mes .mes_buttons .fa-pencil-alt:active::before,
.mes .mes_buttons .fa-pencil-alt:focus::before,
.mes .mes_buttons .fa-pencil-alt:hover::before,
.mes .mes_buttons .fa-edit:active::before,
.mes .mes_buttons .fa-edit:focus::before,
.mes .mes_buttons .fa-edit:hover::before {
  content: '' !important;
  background-image: url('https://iili.io/BTgZyVs.png') !important;
  opacity: 1 !important;
}

.mes .mes_buttons .fa-ellipsis-h:active::before,
.mes .mes_buttons .fa-ellipsis-h:focus::before,
.mes .mes_buttons .fa-ellipsis-h:hover::before,
.mes .mes_buttons .fa-ellipsis-v:active::before,
.mes .mes_buttons .fa-ellipsis-v:focus::before,
.mes .mes_buttons .fa-ellipsis-v:hover::before,
.mes .mes_buttons .fa-ellipsis:active::before,
.mes .mes_buttons .fa-ellipsis:focus::before,
.mes .mes_buttons .fa-ellipsis:hover::before {
  content: '' !important;
  background-image: url('https://iili.io/BTgt9iG.png') !important;
  opacity: 1 !important;
}

/* 隐藏幽灵图标 */
.mes_ghost,
i.mes_ghost,
.mes_ghost.fa-ghost {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}

/* 菜单内的图标保持原样 */
.dropdown-menu .fa-pencil,
.dropdown-menu .fa-pencil-alt,
.dropdown-menu .fa-edit,
.dropdown-menu .fa-ellipsis-h,
.dropdown-menu .fa-ellipsis-v,
.context-menu .fa-pencil,
.context-menu .fa-ellipsis-h,
[role="menu"] .fa-pencil,
[role="menu"] .fa-ellipsis-h {
  background-image: none !important;
  font-size: inherit !important;
  width: auto !important;
  height: auto !important;
}

.dropdown-menu .fa-pencil::before,
.context-menu .fa-pencil::before,
[role="menu"] .fa-pencil::before {
  content: '\f303' !important;
  font-size: inherit !important;
  background-image: none !important;
}

.dropdown-menu .fa-ellipsis-h::before,
.context-menu .fa-ellipsis-h::before,
[role="menu"] .fa-ellipsis-h::before {
  content: '\f141' !important;
  font-size: inherit !important;
  background-image: none !important;
}
/* ================= 时间戳位置调整 ================= */
.timestamp {
    position: absolute !important;
    top: -65px !important;
    right: 10px !important;
    font-size: 12px !important;
    background: transparent !important;
    z-index: 10 !important;
}



/* ================= 名字位置统一调整 ================= */
.name_text {
    position: absolute !important;
    top: -60px !important;
    bottom: auto !important;
    left: 277px !important;
    transform: translateX(-50%) !important;
    font-size: calc(var(--mainFontSize) + 2px) !important; 
    white-space: nowrap !important;
    overflow: visible !important;
    font-family: 'XuanZongTi', 'CooperZhengKai', cursive !important;
    color: #CDDBA4 !important;
}


/* ================= 思维链（暴力修复版） ================= */
.mes_reasoning {
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    margin: 10px 0 !important;
    position: relative !important;
}

/* 完全重建思维链头部 */
.mes_reasoning_header {
    display: flex !important;
    align-items: center !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    margin: 0 0 5px 0 !important;
    min-height: 50px !important;
}

/* 用伪元素显示图片，替代原有内容 */
.mes_reasoning_header::before {
    content: '' !important;
    display: inline-block !important;
    width: 30px !important;
    height: 30px !important;
    background-image: url('https://iili.io/BTcINLB.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: left center !important;
    flex-shrink: 0 !important;
}

/* 隐藏所有原有文字和图标 */
.mes_reasoning_header_title,
.mes_reasoning_header_title *,
.mes_reasoning_arrow,
.mes_reasoning_arrow * {
    display: none !important;
}

/* 思维链内容区域 */
.mes_reasoning_content {
    background: #f5f5f5 !important;
    border-left: 2px solid #FAC5BD !important;
    padding: 16px 16px !important;
    font-size: 13px !important;
    color: #666 !important;
    margin-top: 5px !important;
    clear: both !important;
}
/* ================= 思维链位置调整 ================= */

/* 调整整个思维链容器的位置 */
.mes_reasoning {
    position: relative !important;
    left: 0px !important;      /* 负值向左，正值向右 */
    top: 0px !important;         /* 负值向上，正值向下 */
    margin-left: 0 !important;
    margin-right: 0 !important;
}

/* 或者单独调整思维链头部（图片区域） */
.mes_reasoning_header {
    position: relative !important;
    left: 300px !important;      /* 调整头部水平位置 */
    top: -120px !important;        /* 调整头部垂直位置 */
}

/* 思维链内容区域 - 左右调整 */
.mes_reasoning_content {
    position: relative !important;
    left: 50px !important;          /* 正值向右，负值向左 */
}
/* ================= 下拉菜单 ================= */
.dropdown-menu,
.ui-menu,
#context-menu,
.menu_container,
[class*="dropdown"],
[class*="context-menu"] {
    z-index: 9999 !important;
    position: relative !important;
}

.dropdown-menu,
.dropdown-menu *,
.ui-menu,
.ui-menu *,
.context-menu,
.context-menu *,
.popup-menu,
.popup-menu *,
[role="menu"],
[role="menu"] * {
    pointer-events: auto !important;
    visibility: visible !important;
    opacity: 1 !important;
    z-index: 999999 !important;
    position: fixed !important;
    background: #ffffff !important;
    border: 1px solid #e0e0e0 !important;
}

body,
#app,
#main-content,
.chat-container,
.messages-container {
    overflow: visible !important;
    overflow-x: hidden !important;
}

.mes,
.mes * {
    pointer-events: auto !important;
}

.mes .avatar::after,
.mes::before,
.mes::after {
    pointer-events: none !important;
}

/* ================= 隐藏滚动条 ================= */
::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
    display: none !important;
    background: transparent !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

html, body,
.chat-container,
.messages-container,
.story-container,
.shepherd-element,
.shepherd-content,
div[class*="scroll"],
div[style*="overflow"] {
    overflow: -moz-scrollbars-none !important;
    overflow: auto !important;
    scrollbar-width: none !important;
}

.overflow-y-scroll,
.overflow-auto,
.overflow-x-auto,
.overflow-y-auto {
    overflow: auto !important;
}

/* ================= Toast 提示框 ================= */
#toast-container > .toast {
    background-image: none !important;
    background-color: #FFDBDD !important;
    border: 1px solid #FFA3A1 !important;
    border-radius: 6px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1) !important;
    opacity: 0.95 !important;
    padding: 10px 15px 10px 50px;
    min-height: 30px;
    max-width: 250px;
}

.toast::before {
    content: '';
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    width: 45px;
    height: 45px;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}

.toast-success::before,
.toast-error::before,
.toast-info::before,
.toast-warning::before {
    background-image: url('https://iili.io/BTczQHb.png') !important;
}

.toast-title {
    color: #FEA1A1 !important;
    font-size: 13px;
}

.toast-message {
    color: #FEA1A1 !important;
    font-size: 12px !important;
}

/* ================= 菜单样式整合（灰色已替换为 #FAC5BD） ================= */
.fa, .fa-brands, .fa-classic, .fa-regular, .fa-sharp, .fa-solid:not(.fav_on, .world_set, .fa-power-off), .fab, .far, .fas {
    color: #FAC5BD !important;
    font-size: 15px !important;
    filter: none;
    opacity: 0.9;
}

.menu_button {
    color: #FAC5BD !important;
    filter: none;
    background-color: #ffffff !important;
    border: 1px solid #e0e0e0 !important;
    border-radius: 6px;
}

.inline-drawer-icon {
    -webkit-appearance: none;
    appearance: none;
    width: 24px;
    height: 24px;
    cursor: pointer;
}

.inline-drawer-icon::before {
    display: none !important;
}

.inline-drawer-icon::after {
    content: '' !important;
    display: block !important;
    width: 100% !important;
    height: 100% !important;
    background-image: var(--icon-folder-star) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}

/* 滑动条滑块 */
input[type="range"], input[type="range"]:disabled {
    filter: none;
    box-shadow: none !important;
    background-color: #FAC5BD !important;  /* 轨道颜色改为 #FAC5BD */
    height: 4px !important;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 50px;
    height: 50px;
    box-shadow: none;
    background-color: transparent;
    background-image: url('https://iili.io/BTcxDGt.png') !important;
    background-size: contain;
    background-repeat: no-repeat;
    cursor: pointer;
    border: none;
}

/* Firefox 浏览器兼容 */
input[type="range"]::-moz-range-track {
    background-color: #FAC5BD !important;
    height: 4px !important;
}

input[type="range"]::-moz-range-thumb {
    width: 30px;
    height: 30px;
    background-image: url('https://iili.io/BTczQHb.png') !important;
    background-size: contain;
    background-repeat: no-repeat;
    border: none;
}

/* 勾选框 - 无边框、无阴影、无白色底色，仅图片 */
input[type="checkbox"] {
    -webkit-appearance: none;
    appearance: none;
    width: 30px;
    height: 30px;
    margin: 0;
    padding: 0;
    background: transparent !important;      /* 完全透明背景 */
    border: none !important;                 /* 移除边框 */
    outline: none !important;
    box-shadow: none !important;             /* 移除阴影 */
    position: relative;
    cursor: pointer;
}

/* 未勾选状态 - 使用指定图片 */
input[type="checkbox"]:not(:checked) {
    background-image: url('https://iili.io/BT4gRGp.png') !important;
    background-size: 80% 80% !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
}

/* 勾选状态 - 使用指定图片 */
input[type="checkbox"]:checked {
    background-image: url('https://iili.io/BTgtoib.png') !important;
    background-size: 100% 120% !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
}

/* 移除所有伪元素可能产生的额外内容 */
input[type="checkbox"]::before,
input[type="checkbox"]::after {
    display: none !important;
    content: none !important;
}

/* 禁用悬停/聚焦/激活效果 */
input[type="checkbox"]:hover,
input[type="checkbox"]:focus,
input[type="checkbox"]:active {
    outline: none !important;
    box-shadow: none !important;
    border: none !important;
}

/* 通用输入框 */
input:not(input[type="range"], input[type='checkbox'], input[type='radio'], input[type='submit'], input[type='button']),
select,
.text_pole {
    background-color: #FFDBDD !important;  /* 背景色改为 #FFDBDD */
    border: 1px solid #e0e0e0 !important;
    color: #333 !important;
    padding: 6px 10px;
    transition: all 0.2s ease;
}

input:focus, select:focus, .text_pole:focus {
    border-color: #FAC5BD !important;
    outline: none;
    background-color: #FFDBDD !important;  /* 聚焦时也保持一致 */
}

/* ================= 抽屉和大菜单背景图（强制铺满） ================= */
.inline-drawer-header,
.standoutHeader,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.mes_reasoning_header {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 !important;
}

/* 核心菜单容器：使用新图片并强制铺满 */
.drawer-content,
#options {
    background-image: url('https://iili.io/BTQ7lCG.png') !important;
    background-size: 100% 100% !important;    /* 强制拉伸铺满，不重复 */
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;  /* 确保无底色透出 */
    border-radius: 12px !important;
    border: 1px solid #e0e0e0 !important;
}

/* 确保菜单内所有子元素背景透明，让主背景图透出来 */
.drawer-content *,
#options * {
    background-color: transparent !important;
}

/* 菜单内按钮和选项的样式微调*/
.extension_button,
.menu_button,
.drawer-content button:not(.fa):not([class*="icon"]) {
    background-image: none !important;
    background-color: rgba(255, 255, 255, 0.6) !important; /* 半透白，让背景图可见 */
    border: 1px solid #e0e0e0 !important;
    border-radius: 8px !important;
    color: #FAC5BD !important;
    padding: 6px 12px !important;
    transition: all 0.2s ease !important;
}


/* 下拉选择框等组件背景也设为半透 */
.select2-container--default .select2-selection--multiple {
    background-color: rgba(255, 255, 255, 0.6) !important;
    border: 1px solid #e0e0e0 !important;
    border-radius: 10px !important;
}

.select2-container--default .select2-selection--multiple .select2-selection__choice {
    background-image: none !important;
    background-color: rgba(245, 245, 245, 0.8) !important;
    border: 1px solid #e0e0e0 !important;
    border-radius: 8px !important;
    color: #FAC5BD !important;
}

/* 抽屉头部等样式 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    background-color: rgba(255, 255, 255, 0.6) !important;
    border: 1px solid #e0e0e0 !important;
    border-radius: 12px !important;
    color: #FAC5BD !important;
    width: 100% !important;
    display: flex !important;
    justify-content: space-between !important;
}

#user-settings-block h4 {
    background-color: rgba(245, 245, 245, 0.6) !important;
    border-left: 3px solid #FAC5BD !important;
    margin-top: 12px !important;
    padding: 8px !important;
}
/* 菜单内所有输入框背景色替换为 #E8EEC8 */
.drawer-content input:not([type="range"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]),
#options input:not([type="range"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]),
.drawer-content select,
#options select,
.drawer-content .text_pole,
#options .text_pole,
.drawer-content textarea,
#options textarea {
    background-color: #E8EEC8 !important;
    border: 1px solid #e0e0e0 !important;
    color: #333333 !important;
}

/* 输入框聚焦时效果可选 */
.drawer-content input:focus,
#options input:focus,
.drawer-content select:focus,
#options select:focus,
.drawer-content .text_pole:focus,
#options .text_pole:focus {
    border-color: #FAC5BD !important;
    outline: none !important;
    background-color: #E8EEC8 !important;
}

/* ================= 分割线 ================= */
hr {
    height: 25px !important;
    background-image: url('https://iili.io/BTcz4i7.png') !important;
    background-repeat: repeat-x !important;
    background-position: center !important;
    background-size: auto 500% !important;
    border: none !important;
    box-shadow: none !important;
    margin:  0 !important;
    background-color: transparent !important;
}

/* ================= 换页符图标 ================= */
.swipe_right,
.swipe_left {
    background-image: url('https://iili.io/BTgZtRI.png') !important;
    background-size: contain !important;      /* 改为 contain，完整显示不被裁剪 */
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    /* 扩大容器尺寸 */
    width: 45px !important;
    height: 45px !important;
    overflow: visible !important;
}

.mes .swipe_left {
    transform: scaleX(-1) !important;
}

/* 隐藏原生箭头 */
.mes .swipe_left [class*="fa"],
.mes .swipe_right [class*="fa"],
.mes .swipe_left [class*="chevron"],
.mes .swipe_right [class*="chevron"],
.mes .swipe_left .fa,
.mes .swipe_right .fa,
.mes .swipe_left i,
.mes .swipe_right i {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
    overflow: hidden !important;
    font-size: 0 !important;
}

/* 隐藏伪元素 */
.mes .swipe_left::before,
.mes .swipe_right::before,
.mes .swipe_left::after,
.mes .swipe_right::after {
    display: none !important;
    content: none !important;
}

/* 隐藏数字（换页计数） */
.mes .swipes-counter,
.swipes-counter {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
}

/* 换页符图标位置微调 */
.mes .swipe_right {
    position: relative !important;
    right: -15px !important;      /* 调整右箭头水平位置 */
    top: 0px !important;          /* 调整右箭头垂直位置 */
}

.mes .swipe_left {
    position: relative !important;
    left: -10px !important;       /* 调整左箭头水平位置 */
    top: 0px !important;          /* 调整左箭头垂直位置 */
}

/* ================= 加载动画 ================= */
#preloader {
    position: fixed;
    margin: 0;
    padding: 0;
    top: 0;
    left: 0;
    z-index: 999999;
    width: 100vw;
    height: 100vh;
    background-color: rgba(211,222,191, 0.95) !important;
    opacity: 1;
}

#load-spinner {
    --spinner-size: 80px;
    transition: all var(--animation-duration-2x, 0.3s) ease-out;
    opacity: 1;
    top: calc(50% - var(--spinner-size) / 2);
    left: calc(50% - var(--spinner-size) / 2);
    position: absolute;
    width: var(--spinner-size);
    height: var(--spinner-size);
    /* 替换为您的图片 */
    background-image: url('https://iili.io/BTgtoib.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    /* 移除原来的旋转动画效果（可选） */
    animation: none !important;
}

/* 移除加载动画中的伪元素 */
#load-spinner::before,
#load-spinner::after {
    display: none !important;
    content: none !important;
}

/* ================= 文本样式 ================= */
/* 斜体文本 - 改成细方框框住 */
.mes_text i,
.mes_text em {
    font-style: normal !important;                 /* 取消斜体 */
    text-decoration: none !important;
    display: inline-block !important;              /* 改为 inline-block 让框框生效 */
    border: 1px solid #CDDBA4 !important;          /* 细方框，颜色 #CDDBA4 */
    border-radius: 4px !important;                /* 轻微圆角，不需要可改为 0 */
    padding: 2px 6px !important;                  /* 内边距让文字不贴边 */
    margin: 0 2px !important;
    background: transparent !important;            /* 透明背景 */
    box-decoration-break: clone !important;
    -webkit-box-decoration-break: clone !important;
}

/* 引用文本 - 每一行都有下细横线 */
q {
    font-style: normal !important;
    background: linear-gradient(to top, #FAC5BD 0%, #FAC5BD 2px, transparent 2px) repeat-x !important;
    background-size: 100% 20px !important;
    background-repeat: repeat-x !important;
    background-position: bottom !important;
    padding: 0 2px 2px 2px !important;
    margin: 0 2px !important;
    border-radius: 0 !important;
    display: inline !important;
    white-space: normal !important;
    word-wrap: break-word !important;
    box-decoration-break: clone !important;
    -webkit-box-decoration-break: clone !important;
    line-height: 1.6 !important;
}

/* 万能移除阴影 - 所有元素 */
* {
    -webkit-box-shadow: none !important;
    -moz-box-shadow: none !important;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
    -webkit-filter: none !important;
